+            Result.success,
+            vt_write_until(t, input, input.len, apc_start | apc_end, &stop),
+        );
+        try testing.expectEqual(WriteStop{
+            .consumed = 2,
+            .reached = apc_start,
+            .kind = .apc,
+            .introducer = .esc,
+            .byte = '_',
