+/// Handler counts expected after a complete input.
+const ExpectedCounts = struct {
+    started: usize = 0,
+    ended: usize = 0,
+    dcs_hooks: usize = 0,
+    dcs_unhooks: usize = 0,
+    titles: usize = 0,
+    clipboards: usize = 0,
+
+    fn check(self: ExpectedCounts, h: *BoundaryTestHandler) !void {
